#include "dei_ss_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

typedef struct s_Dei_Ss_Siren_Low_Batt
{
    Vrtc vrtc ; 
}Dei_Ss_Siren_Low_Batt;

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
static void dei_ss_siren_low_batt_execute( void );
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/
static Dei_Ss_Siren_Low_Batt    dei_ss_siren_low_batt_vars;
/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//--------------------------------------------------------------------------//

void dei_ss_siren_low_batt_init( void )
{	
	dei_ss_siren_low_batt_vars.vrtc = vrtc_f_create( (Exec_Func)dei_ss_siren_low_batt_execute ); 
}

//--------------------------------------------------------------------------//

void dei_ss_siren_low_batt_stop( void )
{
	vrtc_stop( dei_ss_siren_low_batt_vars.vrtc );
}

//--------------------------------------------------------------------------//

void dei_ss_siren_low_batt_check( void *remote )
{
	if( remote && (((Cmd_Rf_Pld*)cmd_get_pld(remote))->bits.batt_low) )
	{
		vrtc_stop( dei_ss_siren_low_batt_vars.vrtc ) ; 

		vrtc_update( dei_ss_siren_low_batt_vars.vrtc , DEI_SS_VRTC_TIMEOUT_SIREN_LOW_BATT );

		vrtc_start( dei_ss_siren_low_batt_vars.vrtc );
	}
}

//--------------------------------------------------------------------------//

void dei_ss_siren_low_batt_execute( void )
{
	dei_siren_chirp( DEI_SIREN_DISARM_LOW_BATT ) ;
}

//--------------------------------------------------------------------------//

